using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea.BattleActions;

public class MinimumSoulHeatBasedAction : BattleAction
{
	private const string decreaseSoulHeatID = "DecreaseSoulHeat";

	public const string minimumSoulHeatID = "MinimumSoulHeat";

	[Header("Soul Heat")]
	[SerializeField]
	protected SoulHeat soulHeat;

	[Header("Decrease Soul Heat")]
	[SerializeField]
	protected bool resetSoulHeatAfterUse;

	[SerializeField]
	private bool decreaseSoulHeat;

	[SerializeField]
	[ShowIf("decreaseSoulHeat")]
	private int decreaseSoulHeatAmount;

	public SoulHeat SoulHeat => soulHeat;

	public bool ResetSoulHeatAfterUse => resetSoulHeatAfterUse;

	public bool DecreaseSoulHeat => decreaseSoulHeat;

	public int DecreaseSoulHeatAmount => decreaseSoulHeatAmount;

	public string GetDecreaseSoulHeatLocalized()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("DecreaseSoulHeat"), decreaseSoulHeatAmount);
	}

	public string GetMinimumSoulHeatLocalized(int minimumSoulHeatAmount)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("MinimumSoulHeat"), minimumSoulHeatAmount);
	}

	protected void CheckDecreaseSoulHeat()
	{
		if (resetSoulHeatAfterUse)
		{
			soulHeat.ResetSoulHeat();
		}
		else if (decreaseSoulHeat)
		{
			soulHeat.ModifySoulHeat(-decreaseSoulHeatAmount);
		}
	}

	public int GetSoulHeatAmountToUse(bool activateFeedback)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsDistortionHieroglyphActive(activateFeedback))
		{
			return 10;
		}
		return soulHeat.SoulHeatCounter;
	}

	public int GetSoulHeatAmountToUseAndDecreaseEffect()
	{
		if (soulHeat.SoulHeatCounter >= 10)
		{
			return 10;
		}
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsDistortionHieroglyphActiveAndDecreaseEffect())
		{
			return 10;
		}
		return soulHeat.SoulHeatCounter;
	}

	public void IsDistortionHieroglyphActiveDecreaseEffect(int minimumSoulHeatToCheck)
	{
		if (soulHeat.SoulHeatCounter < minimumSoulHeatToCheck)
		{
			ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsDistortionHieroglyphActiveAndDecreaseEffect();
		}
	}
}
